S_LD_FIX i1, i0, 11;
C_SET_STRIDE_REG i1, 0, 0;
S_LD_FIX i1, i0, 12;
C_SET_STRIDE_REG i1, 0, 1;

;<------------------------------------------------ LOOP Tr Iteration 0 ------------------------------------------------>
;<---------------- Set up Environment (m) ---------------->
