S_ADDI_FIX i1, i0, 1;
; Loop MLEN Times, set a region of m to be negative infinity (negative max)
;<--- LOOP MLEN Times --->
S_ST_FP f1, i1, 0;
S_ADDI_FIX i1, i1, 1;
;<--- LOOP MLEN Times --->
;<---------------- Set up Environment (O) ---------------->
S_LD_FIX i1, i0, 15;
V_RESET_SRAM 0, i1, 0;
;<---------------- Fetch Q ---------------->
S_LD_FIX i1, i0, 13;
S_LD_FIX i2, i0, 6;
S_MUL_FIX i2, i2, i1;
H_PREFETCH_V_H_S i0, i2, a2; 
S_ADDI_FIX i1, i1, 1;
S_ST_FIX i1, i0, 13;
;<--------------------------------  LOOP Tc Iteration 0 -------------------------------->
S_LD_FIX i1, i0, 14;
S_LD_FIX i2, i0, 5;
S_MUL_FIX i2, i2, i1;
H_PREFETCH_M_L_S i0, i2, a2; 
